origin	https://github.com/orin-dx/agent-plugins.git (fetch)
origin	https://github.com/orin-dx/agent-plugins.git (push)
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "changeset@2",
  "title": "Changeset",
  "description": "Describes what was changed in an implementation and why, classified from a consumer's perspective. Supersedes changeset@1 — adds required consumer_impact and semver_impact, set once at authoring time rather than re-derived at release time. Produced by courier's changeset-analyzer, consumed by courier's release-summarizer and by sentinel.",
  "type": "object",
  "required": ["summary", "consumer_impact", "semver_impact", "files_changed", "acceptance_criteria_met"],
  "additionalProperties": false,
  "properties": {
    "summary": {
      "type": "string",
      "maxLength": 200,
      "description": "Description of what changed, from the consumer's perspective. Length and detail scale with semver_impact: one clause for patch/internal-only, one sentence for minor, full detail for major. Under 200 characters."
    },
    "consumer_impact": {
      "type": "string",
      "enum": ["behavior-change", "new-capability", "internal-only"],
      "description": "Whether this change is observable to someone outside this repo. See shared/references/changesets.md for classification rules."
    },
    "semver_impact": {
      "type": "string",
      "enum": ["major", "minor", "patch", "none"],
      "description": "Version bump this change requires, per the Semver Decision Guide in shared/references/changesets.md. release-summarizer takes max(semver_impact) across a release's changesets rather than re-deriving it."
    },
    "files_changed": {
      "type": "array",
      "minItems": 1,
      "items": { "type": "string" },
      "description": "Paths of files added, modified, or deleted"
    },
    "tests_added": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Paths of test files added or modified"
    },
    "acceptance_criteria_met": {
      "type": "array",
      "minItems": 1,
      "items": { "type": "string" },
      "description": "IDs from spec@1.acceptance_criteria that this changeset satisfies"
    },
    "criteria_evidence": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["criterion_id", "test_file", "implementation_file"],
        "additionalProperties": false,
        "properties": {
          "criterion_id": { "type": "string" },
          "test_file": { "type": "string" },
          "test_line": { "type": "integer" },
          "implementation_file": { "type": "string" },
          "implementation_line": { "type": "integer" }
        }
      },
      "description": "Per-criterion evidence trail: exactly where each acceptance_criteria_met ID is tested and implemented. When sourced from implementer's own build, test_line and implementation_line are exact. When reconstructed from a diff with no smith run behind it, file-level entries without line numbers are acceptable rather than fabricating precision that was never observed. A criterion may have more than one entry when it is proven in more than one place."
    },
    "breaking_changes": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Public API or behavior changes that break existing callers. Each entry states old behavior, new behavior, and what the caller does about it."
    },
    "commits": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Git SHAs of commits in this changeset"
    },
    "linked_spec": { "type": "string" },
    "linked_plan": { "type": "string" },
    "linked_requirement": {
      "type": "string",
      "description": "ID of the requirement@1 this change ultimately traces back to. Propagated from spec@1.linked_requirement via plan@1.linked_requirement when available."
    },
    "reasoning": {
      "type": "string",
      "description": "Agent scratchpad — not consumed downstream"
    }
  }
}
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "release-artifact@2",
  "title": "ReleaseArtifact",
  "description": "What was in a release: version, changesets, and breaking changes. Supersedes release-artifact@1 — the changesets array now consumes changeset@2's consumer_impact/semver_impact directly instead of redeclaring a separate type field.",
  "type": "object",
  "required": ["version", "date", "changesets"],
  "additionalProperties": false,
  "properties": {
    "version": {
      "type": "string",
      "description": "Semver version string (e.g. 1.2.0)"
    },
    "date": {
      "type": "string",
      "format": "date",
      "description": "Release date in ISO 8601 format (YYYY-MM-DD)"
    },
    "changesets": {
      "type": "array",
      "minItems": 1,
      "description": "changeset@2 entries included in this release. A changeset IS the changelog entry — semver_impact and consumer_impact are set once at authoring time (shared/schemas/changeset@2.json) and consumed here, not re-derived. release-summarizer's version is max(semver_impact) across this array, with consumer_impact: internal-only entries filtered out before this array is built.",
      "items": {
        "type": "object",
        "required": ["summary", "consumer_impact", "semver_impact"],
        "additionalProperties": false,
        "properties": {
          "summary": {
            "type": "string",
            "description": "One sentence describing what changed, written from the consumer's perspective"
          },
          "consumer_impact": {
            "type": "string",
            "enum": ["behavior-change", "new-capability", "internal-only"]
          },
          "semver_impact": {
            "type": "string",
            "enum": ["major", "minor", "patch", "none"]
          },
          "linked_requirement": {
            "type": "string",
            "description": "ID of the requirement@1 this changeset addresses"
          },
          "pr_url": {
            "type": "string",
            "description": "URL of the merged PR"
          },
          "commits": {
            "type": "array",
            "items": { "type": "string" },
            "description": "Git SHAs included in this changeset"
          }
        }
      }
    },
    "breaking_changes": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Human-readable descriptions of all breaking changes in this release"
    },
    "migration_guide": {
      "type": "string",
      "description": "Optional: instructions for upgrading from the previous version"
    },
    "reasoning": {
      "type": "string",
      "description": "Agent scratchpad — not consumed downstream"
    }
  }
}
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "verdict@1",
  "title": "Verdict",
  "description": "The sentinel exit gate result. Pass or fail, with specific blockers on failure.",
  "type": "object",
  "required": ["verdict", "confidence", "verdict_summary"],
  "additionalProperties": false,
  "properties": {
    "verdict": {
      "enum": ["pass", "fail"],
      "description": "Whether the artifact meets its criteria"
    },
    "confidence": {
      "enum": ["high", "medium", "low"],
      "description": "Confidence in the verdict"
    },
    "blockers": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["criterion", "finding"],
        "additionalProperties": false,
        "properties": {
          "criterion": {
            "type": "string",
            "description": "The specific criterion that failed"
          },
          "finding": {
            "type": "string",
            "description": "What was found — specific, actionable, not generic"
          },
          "location": {
            "type": "string",
            "description": "File path and line number if applicable"
          }
        }
      },
      "description": "Required when verdict is fail. Each blocker must give the producing agent enough information to fix the issue."
    },
    "verdict_summary": {
      "type": "string",
      "maxLength": 300,
      "description": "One paragraph readable by a human or orchestrator. States what passed, what failed, and what happens next."
    },
    "artifact_type": {
      "type": "string",
      "description": "The schema ID of the artifact that was verified (e.g. spec@1)"
    },
    "retry_count": {
      "type": "integer",
      "minimum": 0,
      "description": "How many times this artifact has been through the gate. Escalate at 3."
    },
    "reasoning": {
      "type": "string",
      "description": "Agent scratchpad — not consumed downstream"
    }
  }
}

